\label{Cor_main}
For any $h\in [m+n-1,m+n]$, there exists a sequence of $a$-invariant probability measures $(
u_k)_{k\geq 1}$ on $X_{m+n}$ with $\lim_{k	o\infty}h_{
u_k}(a)=h$ such that its weak$^\ast$ limit $
u$ satisfies $
u(X_{m+n})=h-(m+n-1)$.

For $k\in \mathbb{Z}_{\geq 0}$, fix $0\leq t_k <t_{k+1}$ and $\epsilon_k,\epsilon_{k+1}\geq 0$ and let $\Delta t=\Delta t_k = t_{k+1}-t_k$ and $\Delta \epsilon=\Delta \epsilon_k = \epsilon_{k+1}-\epsilon_k$. Assume that the following formulas hold:
\begin{align}
-\frac{1}{m}\Delta t \leq \Delta \epsilon &\leq \frac{1}{n}\Delta t, \label{Eq_ST1} \\ 
\Delta\epsilon \geq -\frac{n-1}{2n}\Delta t \text{ if } m=1 \text{ and } &\Delta\epsilon \leq \frac{m-1}{2m}\Delta t \text{ if } n=1, \label{Eq_ST2}\\
\text{either } (n-1)(\frac{1}{n}\Delta t -\Delta \epsilon) \geq d\epsilon_k \text{ or } &(m-1)(\frac{1}{m}\Delta t +\Delta\epsilon) \geq d\epsilon_{k+1}. \label{Eq_ST3}
\end{align}
The \textit{standard template} defined by the two points $(t_k, -\epsilon_k)$ and $(t_{k+1},\epsilon_{k+1})$ is the partial template $\mathbf{f}:[t_k,t_{k+1}]\to\mathbb{R}^d$ defined as follows:
\begin{itemize}
\item Let $g_1,g_2:[t_{k},t_{k+1}]\to\mathbb{R}$ be piecewise linear functions such that $g_i(t_j) = -\epsilon_j$, and $g_i$ has two intervals of linearity: one on which $g_i ' =\frac{1}{m}$ and another on which $g_i' =-\frac{1}{n}$. For $i=1$ the latter interval comes first while for $i=2$ the former interval comes first. Finally, let $g_3=\cdots=g_d$ be chosen so that $g_1+\cdots+g_d =0$.
\item For each $t\in[t_k,t_{k+1}]$ let $\mathbf{f}(t)=\mathbf{g}(t)$ if $g_2 (t) \leq g_3 (t)$; otherwise let $f_1(t)=g_1(t)$ and let $f_2(t)=\cdots =f_d(t)$ be chosen so that $f_1+\cdots+f_d = 0$. 
\end{itemize}
Denote the standard template defined by $(t_k,-\epsilon_k)$ and $(t_{k+1},-\epsilon_{k+1})$ by $\mathbf{s}[(t_k,-\epsilon_k),(t_{k+1},-\epsilon_{k+1})]$.

\label{Prop_construction}
Suppose that $(m,n)\neq (1,1)$. Fix $\epsilon>0$ and let $\rho_\epsilon,\eta_\epsilon$ be as in Proposition \ref{Prop_dim}. Then there exists an $a$-invariant probability measure $\mu$ on $X$ such that 
\begin{enumerate}
\item $\operatorname{Supp}\mu \subset  \{x\in X : \rho_\epsilon \leq \lambda_1(x) \leq \eta_\epsilon \}$;
\item $h_\mu(a) \geq m+n-1-\frac{m+n}{mn}\epsilon$.
\end{enumerate}
